// Only a real gap is researched: a numeric gap_id and a topic. check-services.sh once POSTed
// {"gap_id":"probe"} here to prove the webhook answered; 26 such runs searched the web for
// "undefined" and 19 stored junk in the knowledge base. Anything else ends the run here,
// before a search or a 27B call. The webhook item passes through unchanged.
const body = $input.first().json.body || {};
const id = Number(body.gap_id);
const topic = String(body.search_topic ?? '').trim();
if (!Number.isInteger(id) || id <= 0 || topic === '' || topic === 'undefined') {
  return [];
}
return $input.all();

// Parse Ollama response to extract 3 search queries
const ollamaResponse = $input.first().json.response || '';
const searchTopic = $('Knowledge Gap Webhook').first().json.body.search_topic;
const originalQuery = $('Knowledge Gap Webhook').first().json.body.original_query;

let queries = [];

try {
  // Try to parse JSON array from response
  const match = ollamaResponse.match(/\[[\s\S]*?\]/);
  if (match) {
    queries = JSON.parse(match[0]);
  }
} catch (e) {
  // Fallback: split by newlines and clean up
  queries = ollamaResponse.split('\n').filter(l => l.trim().length > 5).slice(0, 3);
}

// Ensure we have at least 1 query
if (queries.length === 0) {
  queries = [searchTopic];
}

// Limit to 3 queries
queries = queries.slice(0, 3);

// Output one item per query
return queries.map((q, i) => ({
  json: {
    query: String(q).replace(/^"|"$/g, ''),
    query_index: i,
    search_topic: searchTopic,
    original_query: originalQuery,
    total_queries: queries.length
  }
}));

// Collect results from all SearXNG searches, deduplicate by URL
const items = $input.all();
const searchTopic = $('Knowledge Gap Webhook').first().json.body.search_topic;
const originalQuery = $('Knowledge Gap Webhook').first().json.body.original_query;

const seenUrls = new Set();
const results = [];

for (const item of items) {
  const searchResults = item.json.results || [];
  // Take top 3 results per query
  const top3 = searchResults.slice(0, 3);

  for (const r of top3) {
    const url = r.url;
    if (!url || seenUrls.has(url)) continue;
    // Skip PDFs, images, videos
    if (/\.(pdf|jpg|png|gif|mp4|avi)$/i.test(url)) continue;
    seenUrls.add(url);
    results.push({
      json: {
        url: url,
        title: r.title || '',
        search_topic: searchTopic,
        original_query: originalQuery,
        total_urls: 0
      }
    });
  }
}

// Set total count and limit to 9
const limited = results.slice(0, 9);
limited.forEach(r => r.json.total_urls = limited.length);

if (limited.length === 0) {
  return [{ json: { error: 'No search results found', search_topic: searchTopic } }];
}

return limited;

// Truncate page content to 8000 chars, strip HTML, filter failed fetches
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  // Skip failed fetches
  if (item.json.error || !item.json.data) continue;

  let content = String(item.json.data || '');

  // Strip HTML tags, scripts, styles
  content = content
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // Skip if too short (likely an error page)
  if (content.length < 100) continue;

  // Truncate to 8000 chars
  content = content.slice(0, 8000);

  // Trace this page back to the URL it was fetched from. Failed fetches leave
  // the success batch, so position i is not the i-th deduplicated URL.
  const source = $('Deduplicate Results').itemMatching(i);
  const url = source ? source.json.url : 'unknown';
  const searchTopic = source ? source.json.search_topic : '';

  output.push({
    json: {
      page_content: content,
      url: url,
      search_topic: searchTopic,
      content_length: content.length
    }
  });
}

if (output.length === 0) {
  return [{ json: { error: 'No pages could be fetched successfully' } }];
}

return output;

// Filter out NOT_RELEVANT responses and errors
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const response = String(item.json.response || '').trim();

  // Skip errors and NOT_RELEVANT
  if (item.json.error) continue;
  if (response === 'NOT_RELEVANT' || response.startsWith('NOT_RELEVANT')) continue;
  // The model sometimes explains instead of answering NOT_RELEVANT. Only the opening is
  // checked, so a real summary that mentions relevance later is kept.
  if (/NOT_RELEVANT|\bnot relevant\b|\birrelevant\b|\bno (relevant|useful) (information|content)\b|\bdoes not (contain|include|provide|mention) any\b/i.test(response.slice(0, 250))) continue;
  if (response.length < 50) continue;

  // Trace back to the page this fact came from; failed extractions leave the batch
  const sourceData = $('Truncate & Clean Content').itemMatching(i) || { json: {} };

  output.push({
    json: {
      summary: response,
      url: sourceData.json.url || 'unknown',
      search_topic: sourceData.json.search_topic || '',
      summary_length: response.length
    }
  });
}

if (output.length === 0) {
  return [{ json: { error: 'No relevant content found', relevant_count: 0 } }];
}

return output;

// Summarize the entire workflow run
const webhookData = $('Knowledge Gap Webhook').first().json.body;
const dedupeItems = $('Deduplicate Results').all();
const filteredItems = $('Filter Relevant Only').all();
const storedItems = $input.all();

const totalUrls = dedupeItems.filter(i => !i.json.error).length;
const relevantCount = filteredItems.filter(i => !i.json.error).length;
const storedCount = storedItems.filter(i => !i.json.error).length;

// The sources this run stored, labelled as Store in Knowledge Base labels them.
// The resolution check always includes their chunks: a top-5 search over the
// whole knowledge base can rank what was just stored out of sight.
const storedSources = [...new Set(storedItems
  .map((item, i) => item.json.error ? null : $('Filter Relevant Only').itemMatching(i))
  .map((filtered) => filtered && filtered.json.url)
  // Only real URLs: Filter Relevant Only falls back to 'unknown' when it cannot trace a page
  .filter((url) => typeof url === 'string' && url.length > 0 && url !== 'unknown')
  .map((url) => 'n8n-gap|' + url))];

const summary = {
  status: 'completed',
  gap_id: webhookData.gap_id,
  search_topic: webhookData.search_topic,
  original_query: webhookData.original_query,
  stored_sources: storedSources,
  timestamp: new Date().toISOString(),
  stats: {
    pages_fetched: totalUrls,
    relevant_pages: relevantCount,
    chunks_stored: storedCount
  }
};

console.log('[N8N Knowledge Gap] ' + JSON.stringify(summary));

return [{ json: summary }];

// Log the resolution result. The app returns a three-way verdict; "review"
// means the scorer was not confident either way, so the gap is parked for a
// human and does NOT spend a retry.
//
// Check Gap Resolution runs with onError: continueErrorOutput and BOTH of its
// outputs arrive here, so a scorer outage, a 500, a 404, a malformed
// config/decide.yaml or a 120s timeout reaches this node as an error item. A
// failed call is not a verdict: logging it as "unresolved" would assert a
// judgment nobody made, which is exactly the defect (a missing answer read as
// a confident one) that this feature removed from the app. So the failure case
// is detected FIRST and gets its own status; the database row is untouched
// either way, and this log is the only operator-visible record of the run.
const resolution = $input.first().json;
const summary = $('Summary & Log').first().json;

const STATUS_BY_VERDICT = {
  resolved: 'gap_resolved',
  review: 'gap_review',
  unresolved: 'gap_still_open',
};

// n8n hands an error item either a string or an object with a message.
function errorDetailOf(err) {
  if (err === undefined || err === null) return null;
  if (typeof err === 'string') return err;
  if (typeof err === 'object' && typeof err.message === 'string') return err.message;
  return JSON.stringify(err);
}

const errorDetail = errorDetailOf(resolution.error);

// An app build older than the three-way verdict answers with a boolean and no
// verdict. That is a real judgment, so it still maps -- but only when the call
// itself succeeded.
let verdict = typeof resolution.verdict === 'string' ? resolution.verdict : null;
if (verdict === null && errorDetail === null && typeof resolution.resolved === 'boolean') {
  verdict = resolution.resolved ? 'resolved' : 'unresolved';
}

// hasOwnProperty, so that a verdict of "constructor" is a failure and not a
// status built out of Object.prototype.
const known = verdict !== null && Object.prototype.hasOwnProperty.call(STATUS_BY_VERDICT, verdict);
const failed = errorDetail !== null || !known;

const result = {
  status: failed ? 'gap_decision_failed' : STATUS_BY_VERDICT[verdict],
  // null rather than a guess: nothing was decided this run.
  verdict: failed ? null : verdict,
  probability: !failed && typeof resolution.probability === 'number' ? resolution.probability : null,
  gap_id: summary.gap_id,
  search_topic: summary.search_topic,
  original_query: summary.original_query,
  resolved: failed ? null : verdict === 'resolved',
  error: failed
    ? (errorDetail !== null
        ? errorDetail
        : 'the app returned no usable verdict' + (verdict !== null ? ' ("' + verdict + '")' : ''))
    : null,
  ingestion_stats: summary.stats,
  timestamp: new Date().toISOString()
};

console.log('[N8N Resolution] ' + JSON.stringify(result));

return [{ json: result }];

// SearXNG failed — log error and stop gracefully
const searchTopic = $('Knowledge Gap Webhook').first().json.body.search_topic;
console.log('[N8N] SearXNG search failed for topic: ' + searchTopic);
return [{
  json: {
    status: 'error',
    stage: 'searxng_search',
    search_topic: searchTopic,
    message: 'SearXNG search failed. Check that SearXNG is running on localhost:8888.'
  }
}];

// Ollama query generation failed — fallback to using search_topic directly
const searchTopic = $('Knowledge Gap Webhook').first().json.body.search_topic;
const originalQuery = $('Knowledge Gap Webhook').first().json.body.original_query;

console.log('[N8N] Ollama query generation failed, using search_topic as fallback');

return [{
  json: {
    query: searchTopic,
    query_index: 0,
    search_topic: searchTopic,
    original_query: originalQuery,
    total_queries: 1
  }
}];
